/*
 * Trace points are compiled out. The arguments stay type-checked and
 * "used" (no unused-variable warnings) through a never-called sink.
 * Names are listed in xfs_trace_names.h (generated by tools/gen-trace-stubs.sh).
 */
#ifndef WFS_SHIM_TRACE_BASE_H
#define WFS_SHIM_TRACE_BASE_H

static inline void wfs_trace_sink(int unused, ...) { (void)unused; }
#define WFS_TRACE(...)	do { if (0) wfs_trace_sink(0, ##__VA_ARGS__); } while (0)

/* Hand-written: used by tests/test_shim.c. */
#define trace_xfs_shim_test_event(...)	WFS_TRACE(__VA_ARGS__)

#endif
